import React from 'react'
import { useEffect, useState } from 'react'
import HomePage from './pages/HomePage'
import ServicesPage from './pages/ServicesPage'
import InvestFinanceValuePage from './pages/InvestFinanceValuePage'
import PlanLeaseOccupyPage from './pages/PlanLeaseOccupyPage'
import DesignBuildPage from './pages/DesignBuildPage'

function App() {
  const [page, setPage] = useState('home')

  useEffect(() => {
    const path = window.location.pathname
    if (path.includes('services-invest-finance-value')) setPage('invest')
    else if (path.includes('services-plan-lease-occupy')) setPage('plan')
    else if (path.includes('services-design-build')) setPage('design')
    else if (path.includes('services')) setPage('services')
    else setPage('home')
  }, [])

  const navigate = (target: string) => {
    setPage(target)
    let url = '/'
    if (target === 'services') url = '/services.html'
    if (target === 'invest') url = '/services-invest-finance-value.html'
    if (target === 'plan') url = '/services-plan-lease-occupy.html'
    if (target === 'design') url = '/services-design-build.html'
    window.history.pushState({}, '', url)
  }

  return (
    <>
      {page === 'home' && <HomePage navigate={navigate} />}
      {page === 'services' && <ServicesPage navigate={navigate} />}
      {page === 'invest' && <InvestFinanceValuePage navigate={navigate} />}
      {page === 'plan' && <PlanLeaseOccupyPage navigate={navigate} />}
      {page === 'design' && <DesignBuildPage navigate={navigate} />}
    </>
  )
}

export default App
EOF
