import React, { useState, useRef, useEffect } from 'react'
import { Menu, X, ChevronDown, Building2 } from 'lucide-react'

interface HeaderProps {
  navigate: (page: string) => void
  currentPage?: string
}

const serviceNeeds = [
  { label: 'Invest, Finance & Value', page: 'invest' },
  { label: 'Plan, Lease & Occupy', page: 'plan' },
  { label: 'Design & Build', page: 'design' },
  { label: 'Manage Properties & Portfolios', page: 'services' },
  { label: 'Transform Business Outcomes', page: 'services' },
]

const propertyTypes = [
  { label: 'Office', page: 'services' },
  { label: 'Retail', page: 'services' },
  { label: 'Industrial', page: 'services' },
  { label: 'Multifamily', page: 'services' },
  { label: 'Hotels', page: 'services' },
]

const navItems = [
  { label: 'Services', hasDropdown: true },
  { label: 'Insights & Research', page: 'services' },
  { label: 'Properties', page: 'services' },
  { label: 'People & Offices', page: 'services' },
  { label: 'Careers', page: 'services' },
  { label: 'About Us', page: 'services' },
]

export default function Header({ navigate, currentPage = 'home' }: HeaderProps) {
  const [mobileOpen, setMobileOpen] = useState(false)
  const [megaOpen, setMegaOpen] = useState(false)
  const [mobileServicesOpen, setMobileServicesOpen] = useState(false)
  const megaRef = useRef<HTMLDivElement>(null)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (megaRef.current && !megaRef.current.contains(e.target as Node)) {
        setMegaOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const handleNav = (page: string) => {
    navigate(page)
    setMegaOpen(false)
    setMobileOpen(false)
  }

  const onMegaEnter = () => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current)
    setMegaOpen(true)
  }

  const onMegaLeave = () => {
    timeoutRef.current = setTimeout(() => setMegaOpen(false), 150)
  }

  return (
    <header className="sticky top-0 z-50 bg-gs-navy text-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16 lg:h-20">
          {/* Logo */}
          <button
            onClick={() => handleNav('home')}
            className="flex items-center gap-2 group"
          >
            <Building2 className="w-7 h-7 text-gs-gold transition-transform group-hover:scale-110" />
            <span className="text-xl lg:text-2xl font-serif font-bold tracking-tight">
              GlobalStone
            </span>
          </button>

          {/* Desktop Nav */}
          <nav className="hidden lg:flex items-center gap-1">
            {navItems.map((item) => (
              <div
                key={item.label}
                className="relative"
                onMouseEnter={item.hasDropdown ? onMegaEnter : undefined}
                onMouseLeave={item.hasDropdown ? onMegaLeave : undefined}
                ref={item.hasDropdown ? megaRef : undefined}
              >
                <button
                  onClick={() => {
                    if (!item.hasDropdown && item.page) handleNav(item.page)
                    if (item.hasDropdown) setMegaOpen((v) => !v)
                  }}
                  className="flex items-center gap-1 px-4 py-2 text-sm font-medium text-white/90 hover:text-white transition-colors rounded-md hover:bg-white/5"
                >
                  {item.label}
                  {item.hasDropdown && (
                    <ChevronDown
                      className={`w-4 h-4 transition-transform ${megaOpen ? 'rotate-180' : ''}`}
                    />
                  )}
                </button>

                {/* Mega Menu */}
                {item.hasDropdown && megaOpen && (
                  <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-[720px] bg-white text-gs-navy rounded-lg shadow-2xl border border-gs-gray overflow-hidden">
                    <div className="grid grid-cols-2 gap-0">
                      <div className="p-6 border-r border-gs-gray">
                        <h3 className="text-xs font-bold uppercase tracking-wider text-gs-gray-dark mb-4 font-sans">
                          By Need
                        </h3>
                        <ul className="space-y-1">
                          {serviceNeeds.map((s) => (
                            <li key={s.label}>
                              <button
                                onClick={() => handleNav(s.page)}
                                className="w-full text-left px-3 py-2.5 text-sm font-medium rounded-md hover:bg-gs-cream hover:text-gs-teal transition-colors"
                              >
                                {s.label}
                              </button>
                            </li>
                          ))}
                        </ul>
                      </div>
                      <div className="p-6">
                        <h3 className="text-xs font-bold uppercase tracking-wider text-gs-gray-dark mb-4 font-sans">
                          By Property Type
                        </h3>
                        <ul className="space-y-1">
                          {propertyTypes.map((s) => (
                            <li key={s.label}>
                              <button
                                onClick={() => handleNav(s.page)}
                                className="w-full text-left px-3 py-2.5 text-sm font-medium rounded-md hover:bg-gs-cream hover:text-gs-teal transition-colors"
                              >
                                {s.label}
                              </button>
                            </li>
                          ))}
                        </ul>
                      </div>
                    </div>
                    <div className="px-6 py-3 bg-gs-cream border-t border-gs-gray">
                      <button
                        onClick={() => handleNav('services')}
                        className="text-sm font-semibold text-gs-teal hover:text-gs-gold transition-colors"
                      >
                        View All Services →
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </nav>

          {/* Mobile menu button */}
          <button
            className="lg:hidden p-2 rounded-md hover:bg-white/10 transition-colors"
            onClick={() => setMobileOpen(!mobileOpen)}
            aria-label="Toggle menu"
          >
            {mobileOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>
      </div>

      {/* Mobile Nav */}
      {mobileOpen && (
        <div className="lg:hidden bg-gs-navy border-t border-white/10">
          <div className="px-4 py-4 space-y-1">
            {navItems.map((item) => (
              <div key={item.label}>
                {item.hasDropdown ? (
                  <div>
                    <button
                      onClick={() => setMobileServicesOpen(!mobileServicesOpen)}
                      className="flex items-center justify-between w-full px-3 py-3 text-sm font-medium text-white/90 hover:text-white hover:bg-white/5 rounded-md transition-colors"
                    >
                      {item.label}
                      <ChevronDown
                        className={`w-4 h-4 transition-transform ${mobileServicesOpen ? 'rotate-180' : ''}`}
                      />
                    </button>
                    {mobileServicesOpen && (
                      <div className="mt-1 ml-4 space-y-1 border-l border-white/10 pl-3">
                        <p className="px-3 py-1 text-xs font-bold uppercase tracking-wider text-white/50">
                          By Need
                        </p>
                        {serviceNeeds.map((s) => (
                          <button
                            key={s.label}
                            onClick={() => handleNav(s.page)}
                            className="w-full text-left px-3 py-2 text-sm text-white/80 hover:text-white hover:bg-white/5 rounded-md transition-colors"
                          >
                            {s.label}
                          </button>
                        ))}
                        <p className="px-3 py-1 text-xs font-bold uppercase tracking-wider text-white/50 mt-2">
                          By Property Type
                        </p>
                        {propertyTypes.map((s) => (
                          <button
                            key={s.label}
                            onClick={() => handleNav(s.page)}
                            className="w-full text-left px-3 py-2 text-sm text-white/80 hover:text-white hover:bg-white/5 rounded-md transition-colors"
                          >
                            {s.label}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                ) : (
                  <button
                    onClick={() => item.page && handleNav(item.page)}
                    className="w-full text-left px-3 py-3 text-sm font-medium text-white/90 hover:text-white hover:bg-white/5 rounded-md transition-colors"
                  >
                    {item.label}
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
