                className={`group p-6 lg:p-8 border border-gs-gray rounded-lg hover:shadow-xl hover:border-gs-gold/30 transition-all duration-500 ${isVisible['design-capabilities'] ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-6'}`}
                style={{ transitionDelay: `${i * 100}ms` }}
              >
                <cap.icon className="w-10 h-10 text-gs-gold mb-5" />
                <h3 className="text-xl font-serif font-semibold text-gs-navy mb-3 group-hover:text-gs-teal transition-colors">
                  {cap.title}
                </h3>
                <p className="text-sm text-gs-gray-dark leading-relaxed mb-5">
                  {cap.description}
                </p>
                <button
                  onClick={() => navigate('services')}
                  className="inline-flex items-center gap-1.5 text-sm font-semibold text-gs-teal hover:text-gs-gold transition-colors"
                >
                  Learn More
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Partnership Highlight */}
      <section
        id="partnership"
        ref={setRef('partnership')}
        className="py-16 lg:py-24 bg-gs-navy"
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
            <div
              className={`transition-all duration-700 ${isVisible['partnership'] ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-6'}`}
            >
              <span className="inline-block px-3 py-1 text-xs font-bold uppercase tracking-wider bg-gs-gold/20 text-gs-gold rounded-full mb-6">
                Partnership
              </span>
              <h2 className="text-3xl lg:text-4xl text-white mb-6">
                Integrated Delivery, Global Reach
              </h2>
              <p className="text-white/80 leading-relaxed mb-6">
                GlobalStone's Design & Build division partners with leading architecture, engineering, and construction firms worldwide to deliver turnkey solutions. Our integrated approach ensures seamless coordination from concept through occupancy.
              </p>
              <ul className="space-y-3 mb-8">
                {[
                  'Seamless coordination from concept through occupancy',
                  'Proprietary project management methodology',
                  'Global network of vetted contractors and suppliers',
                  'Real-time cost and schedule tracking',
                ].map((item) => (
                  <li key={item} className="flex items-start gap-3 text-white/80 text-sm">
                    <CheckCircle className="w-5 h-5 text-gs-gold shrink-0 mt-0.5" />
                    {item}
                  </li>
                ))}
              </ul>
              <button
                onClick={() => navigate('services')}
                className="inline-flex items-center gap-2 px-6 py-3 bg-gs-gold text-gs-navy font-semibold rounded-md hover:bg-gs-gold-light transition-colors"
              >
                Explore Partnerships
                <ArrowRight className="w-4 h-4" />
              </button>
            </div>
            <div
              className={`grid grid-cols-2 gap-4 transition-all duration-700 delay-200 ${isVisible['partnership'] ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-6'}`}
            >
              {partnershipStats.map((stat) => (
                <div
                  key={stat.label}
                  className="p-6 bg-white/5 border border-white/10 rounded-lg text-center"
                >
                  <p className="text-3xl lg:text-4xl font-serif font-bold text-gs-gold mb-2">
                    {stat.value}
                  </p>
                  <p className="text-sm text-white/70">{stat.label}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      <Footer navigate={navigate} />
    </div>
  )
}
EOF

